import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/forge/commands.md","filePath":"en/modules/forge/commands.md","lastUpdated":0}`),a={name:`en/modules/forge/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to “Commands and Permissions”">​</a></h1><p>The main command of EmakiForge is <code>/emakiforge</code>, with <code>/eforge</code> and <code>/ef</code> as aliases. Commands open the forge GUI, open the recipe book, list recipes, reload configuration, and print debug information.</p><p>The root command requires <code>emakiforge.use</code> (default true). Additional subcommand permissions are listed below.</p><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/ef help</code></td><td>Root permission only</td><td>Show command help. Running the root command with no arguments also shows help.</td></tr><tr><td><code>/ef forge</code></td><td>Root permission only</td><td>Open the forge GUI. Players only (console senders see the player-only message).</td></tr><tr><td><code>/ef book</code></td><td><code>emakiforge.book</code> or <code>emakiforge.admin</code></td><td>Open the recipe book. Players only (console senders see the player-only message).</td></tr><tr><td><code>/ef list &lt;type&gt;</code></td><td><code>emakiforge.admin</code></td><td>List loaded definitions with display names. Only <code>recipe</code> is implemented (<code>recipes</code> is also accepted) and tab completion only suggests <code>recipe</code>; any other value reports invalid arguments.</td></tr><tr><td><code>/ef reload</code></td><td><code>emakiforge.reload</code> or <code>emakiforge.admin</code></td><td>Reload config, language, GUI templates, and recipes, reporting the reloaded recipe and GUI template counts plus the elapsed time.</td></tr><tr><td><code>/ef convert-legacy [confirm]</code></td><td><code>emakiforge.admin</code></td><td>Migrates legacy <code>item_sources</code> under <code>materials[]</code>, <code>blueprint_requirements[]</code>, and <code>result.*.outputs[]</code> in <code>recipes/</code>; material entries keep the legacy key by spec. Without an argument it performs a dry run; <code>confirm</code> (or <code>--apply</code>) writes files and leaves a <code>.bak</code> backup.</td></tr><tr><td><code>/ef debug stats</code></td><td><code>emakiforge.debug</code> or <code>emakiforge.admin</code></td><td>Print runtime metrics and the recipe load report (<code>status</code> is equivalent).</td></tr><tr><td><code>/ef debug on</code> / <code>off</code></td><td><code>emakiforge.debug</code> or <code>emakiforge.admin</code></td><td>Toggle debug output globally.</td></tr><tr><td><code>/ef debug player &lt;player&gt;</code></td><td><code>emakiforge.debug</code> or <code>emakiforge.admin</code></td><td>Track debug output for one player.</td></tr><tr><td><code>/ef debug module &lt;module&gt;</code></td><td><code>emakiforge.debug</code> or <code>emakiforge.admin</code></td><td>Enable debug output for one submodule.</td></tr></tbody></table><p>Available debug submodules: <code>recipe</code>, <code>forge</code>, <code>gui</code>, <code>pdc</code>. Any other <code>/ef debug</code> argument is handled by the CoreLib debug command.</p><p>The aliases <code>eforge</code> and <code>ef</code> behave exactly like the root command (same TabExecutor).</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to “Permissions”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakiforge.use</code></td><td>true</td><td>Allows use of the root command and forge GUI.</td></tr><tr><td><code>emakiforge.book</code></td><td>true</td><td>Allows opening the recipe book.</td></tr><tr><td><code>emakiforge.reload</code></td><td>op</td><td>Allows reloading configuration.</td></tr><tr><td><code>emakiforge.debug</code></td><td>op</td><td>Allows debug output.</td></tr><tr><td><code>emakiforge.admin</code></td><td>op</td><td>Allows administrative operations.</td></tr></tbody></table><h2 id="which-command-first" tabindex="-1">Which command first <a class="header-anchor" href="#which-command-first" aria-label="Permalink to “Which command first”">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Run first</th><th>Purpose</th></tr></thead><tbody><tr><td>A player wants to forge</td><td><code>/ef forge</code></td><td>Open the forge GUI.</td></tr><tr><td>A player cannot find a recipe</td><td><code>/ef book</code></td><td>Check whether the recipe is loaded.</td></tr><tr><td>An admin changed recipes or GUI files</td><td><code>/ef reload</code></td><td>Reload <code>recipes/</code>, <code>gui/</code>, language, and runtime resources.</td></tr><tr><td>Unsure whether a recipe loaded</td><td><code>/ef list recipe</code></td><td>Inspect the loaded recipe list.</td></tr><tr><td>Recipe load warnings or errors</td><td><code>/ef debug stats</code></td><td>Inspect runtime metrics and the recipe load report.</td></tr><tr><td>Unexpected forge results</td><td><code>/ef debug module forge</code></td><td>Turn on debug output for the <code>forge</code> submodule.</td></tr></tbody></table><p>After editing <code>recipes/</code>, <code>gui/</code>, or the language files, run <code>/ef reload</code>; it reports the reloaded recipe and GUI template counts. Back up the recipe files you are debugging before reloading.</p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};